{
  "checks": [
    {
      "problem": "对比度、色差等检测明细表只按位置名或颜色对列行、不带问题编号,位置写法还与问题清单不一致,读者无法把某一行数值直接对到某条问题",
      "A": "没解决",
      "B": "部分解决"
    },
    {
      "problem": "问题清单的「影响」列用色觉类型缩写、表头还被页面边缘截断,与「按色盲类型」里的全称对不上",
      "A": "没解决",
      "B": "解决"
    },
    {
      "problem": "修复动作表里有些改动行匹配不到问题编号(显示「—」),读者无法判断这些改动覆盖了哪条问题、还是有问题漏了修复",
      "A": "部分解决",
      "B": "解决"
    }
  ],
  "worse": [
    {
      "version": "B",
      "where": "「色板与对比度」下的文字对比度表(编号列)",
      "why": "把对比度行硬套上问题编号:拥堵路段上的路名(2.22 不通过)和严重拥堵路段上的路名(8.36 通过)都被标成 P1,而 P1 是「畅通与拥堵对红绿色盲几乎同色」的混淆色问题,与文字对比度无关;问题清单里也没有覆盖这两行的对比度条目(P4 只对应畅通路段)。读者按编号反查会把对比度问题配到混淆色条目上。表下的「空编号为未列入问题清单的检查项」在这张表里又找不到任何空编号行,反而让人以为这四行都有对应问题。A 版这里不写编号,虽不能直接对照,但不会给出错误对应。"
    }
  ],
  "better": "B",
  "reason": "B 在两张检测明细表里都加了问题编号列、并加了「空编号为未列入问题清单的检查项」的说明,问题清单的「影响」列也改成色觉类型全称、表头不再被截断,读者在表内就能对到编号、确认影响类型,少了一轮按位置名和「红/绿/蓝」缩写的来回配对;A 版这两处都还缺。代价是 B 的文字对比度表编号映射有误。",
  "next": [
    {
      "where": "「色板与对比度」的文字对比度表",
      "task": "读者想确认「拥堵路段上的路名不通过」属于哪条问题、要不要补进修复清单",
      "why": "该行被标为 P1,而 P1 是混淆色问题;问题清单里只有 P4 覆盖对比度不足且只针对畅通路段,读者按编号反查会配错,也看不出这一条是否漏报。"
    },
    {
      "where": "「下一步」",
      "task": "读者想按严重度排修复先后",
      "why": "「下一步」只重复标题和建议,没有严重度标签,读者要滚回上面的「问题清单」才能确认哪条是高、哪条是中,再判断 P1/P3/P2/P4 的顺序含义。"
    },
    {
      "where": "「模拟视图」的四张地图缩略图",
      "task": "读者想看图验证「畅通与拥堵同色」「畅通与缓行难分」到底出现在哪条路",
      "why": "图上没有标出问题涉及的路段或编号,读者要自己在四张缩略图之间找同一段路,再回「颜色混淆」明细和「问题清单」对照,来回翻找多。"
    }
  ]
}
